    "citations": [
      {"article_id": "HCMUT_HOCPHI2800_Dieu_7", "law_name": "Quy định gia hạn thời gian nộp học phí đối với người học tại Trường Đại học Bách khoa – Đại học Quốc gia TP. HCM. — số 2800/QĐ-ĐHBK", "exact_quote": "Bước 1: Người học nộp đơn đăng ký gia hạn thời gian nộp học phí về Phòng Công tác sinh viên..."},
